reserveMedian = values =&gt; {
  const sorted = [...values].sort((a, b) =&gt; a - b)
  const middle = Math.floor(sorted.length / 2)
  return sorted.length % 2
    ? sorted[middle]
    : (sorted[middle - 1] + sorted[middle]) / 2
}

reserveSummaryRows = [2, 5, 10, 15].map(target =&gt; {
  const rows = reserveRows.filter(d =&gt; d.reserve_target_pct === target)
  const needed = rows.map(d =&gt; d.additional_spaces_needed)
  const short = needed.filter(d =&gt; d &gt; 0)
  return {
    target,
    nights: rows.length,
    shortfallNights: short.length,
    shortfallPct: 100 * short.length / rows.length,
    medianAll: reserveMedian(needed),
    medianWhenShort: reserveMedian(short),
    maximum: Math.max(...needed),
    bedNights: needed.reduce((sum, value) =&gt; sum + value, 0)
  }
})























