mixEmergAnomaly = {
  const m = bq("mix_emerg")
  const mc = cr("mix_emerg")
  if (!m || !mc || mc.city_cap == null || m.cap == null || m.cap_funding == null) return md``
  const city   = mc.city_cap
  const actual = m.cap
  const funded = m.cap_funding
  // Build a short, factual call-out describing whichever shape the anomaly takes.
  let sentence
  if (city &gt; funded) {
    sentence = `The Mixed Adult Emergency row does not make sense from the public numbers. The City's webpage shows **${n(city)}** beds. Its public file says only **${n(funded)}** beds were funded. The webpage therefore shows **${n(city - funded)} more beds than the funded number**. The City has not explained why.`
  } else if (city &lt; actual) {
    sentence = `The Mixed Adult Emergency row does not make sense from the public numbers. The City's webpage shows **${n(city)}** beds. That is **${n(actual - city)} fewer** than its public file shows as open and **${n(funded - city)} fewer** than it shows as funded. The City has not explained why.`
  } else {
    sentence = `The Mixed Adult Emergency row does not match either number in the public file. The City's webpage shows **${n(city)}** beds. Its public file shows **${n(actual)}** open and **${n(funded)}** funded. The City has not explained why.`
  }
  return md`${sentence}`
}








A program missing from the public data file
On May 14, the City webpage showed 29 people in Bridging & Triage Programs. The public data file did not include this program at all. That means the file alone cannot give the same total as the webpage. BonQuery has asked the City to add this program to its public file.


Does the City change old data?
We save a copy of the City’s file each time we update. A computer then checks whether the City changed any earlier row. If it did, BonQuery sends an email. The May 14 numbers have not changed since we first saved them on May 17, 2026.


What this means
The City publishes shelter numbers on a webpage and in a public data file. They often do not match. BonQuery shows the differences and saves the evidence so the checks can be repeated.
